using UnityEngine;
namespace KaisarMMO.UI{public class MobileControls:MonoBehaviour{public PlayerInputBridge bridge;public void Move(Vector2 v){bridge?.SetMove(v);}public void Sprint(bool v){bridge?.SetSprint(v);}public void Attack(){bridge?.Attack();}}public class PlayerInputBridge:MonoBehaviour{Vector2 move;bool sprint;public void SetMove(Vector2 v){move=Vector2.ClampMagnitude(v,1);}public void SetSprint(bool v){sprint=v;}public void Attack(){var c=GetComponent<KaisarMMO.Combat.CombatController>();c?.RequestAttack();}void Update(){var p=GetComponent<KaisarMMO.Player.PlayerController>();p?.Move(move,sprint);}}}
